	title 'QD Shifts            GS ROM 2.0'*****************************************************************			   **              SHIFTS		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1987	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	blanks off	string asis		include 'all.macros'	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2';                COPY SHIFTS/SHIFTS****************************************************************** ShiftStay** This is called with the word to be shifted in the a-reg.** The second entry point is for callers	that don't want to* use HowFarToShift	on ZP.*****************************************************************	EXPORT ShiftStayShiftStay	PROC	ldx HowFarToShift	EXPORT xShiftStayxShiftStay		;       	jmp (Table,x)Table	DC.W Shift0	DC.W Shift1	DC.W Shift2	DC.W Shift3	DC.W Shift4	DC.W Shift5	DC.W Shift6	DC.W Shift7	DC.W Shift8	DC.W Shift9	DC.W Shift10	DC.W Shift11	DC.W Shift12	DC.W Shift13	DC.W Shift14	DC.W Shift15Shift15		; 	rol a	and #%0000000100000000	rtlShift14		; 	rol a	rol a	and #%0000001100000000	rtlShift13		; 	rol a	rol a	rol a	and #%0000011100000000	rtlShift12		; 	rol a	rol a	rol a	rol a	and #%0000111100000000	rtlShift11	xba	lsr a	lsr a	lsr a	and #%0001111100000000	rtlShift10	xba	lsr a	lsr a	and #%0011111100000000	rtlShift9	xba	lsr a	and #%0111111100000000	rtlShift8	xba	and #%1111111100000000	rtl; 123456789ooooooo initial bits; 9ooooooo12345678 initial word; 123456789ooooooo swap to get bits in right order for shifting; ooooooo123456789 shift; 23456789ooooooo1 swap to get final word; ooooooo123456789 final bits	GOTO .skipShift7	xba	; 3	lsr a	; 2	lsr a	; 2	lsr a	; 2	lsr a	; 2	lsr a	; 2	lsr a	; 2	lsr a	; 2	xba	; 3	rtl.skipShift7	clc	; 2	adc #$8000	; 3 move high bit to carry	rol a	; 2 rotate carry into low end	and #%0000000111111111 ; 3	xba	; 3	rtlShift6	xba	lsr a	lsr a	lsr a	lsr a	lsr a	lsr a	xba	rtlShift5	xba	lsr a	lsr a	lsr a	lsr a	lsr a	xba	rtlShift4	xba	lsr a	lsr a	lsr a	lsr a	xba	rtlShift3	xba	lsr a	lsr a	lsr a	xba	rtlShift2	xba	lsr a	lsr a	xba	rtlShift1	xba	lsr a	xba	rtlShift0	rtl	ENDP****************************************************************** ShiftOut** This is called with the word to be shifted in the a-reg.* We read how far to shift and use the table to shift the* right number of times.** The second entry point is for routines that want to use these* shifts and not use HowFarToShift on zero page.*****************************************************************	EXPORT ShiftOutShiftOut	PROC	ldx HowFarToShift	EXPORT xShiftOutxShiftOut		;       	jmp (Table,x)Table	DC.W Shift0	DC.W Shift1	DC.W Shift2	DC.W Shift3	DC.W Shift4	DC.W Shift5	DC.W Shift6	DC.W Shift7	DC.W Shift8	DC.W Shift9	DC.W Shift10	DC.W Shift11	DC.W Shift12	DC.W Shift13	DC.W Shift14	DC.W Shift15Shift0	lda #0	rtl;xxxxxxxxxxxxxxx1	  initial bits;xxxxxxx1xxxxxxxx	  initial word;oooooooo1ooooooo	  final word;1xxxxxxxxxxxxxxx	  final bitsShift1	ror a	and #%0000000010000000	rtl;xxxxxxxxxxxxxx12	   initial bits;xxxxxx12xxxxxxxx;xxxxxxxx12xxxxxx;12xxxxxxxxxxxxxx	   final bitsShift2	ror a	ror a	and #%0000000011000000	rtlShift3	ror a	ror a	ror a	and #%0000000011100000	rtlShift4	ror a	ror a	ror a	ror a	and #%0000000011110000	rtl; xxxxxxxxxxx12345; xxx12345xxxxxxxx; oooooooo12345ooo; 12345xxxxxxxxxxxShift5	xba	rol a	rol a	rol a	and #%0000000011111000	rtlShift6	xba	rol a	rol a	and #%0000000011111100	rtlShift7	xba	rol a	and #%0000000011111110	rtlShift8	xba	and #%0000000011111111	rtl; xxxxxxx123456789	  initial bits; 23456789xxxxxxx1	  initial word; 9ooooooo12345678	  final word; 123456789xxxxxxx	  final bitsShift9	xba	; 3	ror a	; 2	php	; 3	asl a	; 2	plp	; 4	ror a	; 2	and #%1000000011111111 ; 3	rtlShift10	xba	asl a	asl a	asl a	asl a	asl a	asl a	xba	rtlShift11	xba	asl a	asl a	asl a	asl a	asl a	xba	rtlShift12	xba	asl a	asl a	asl a	asl a	xba	rtlShift13	xba	asl a	asl a	asl a	xba	rtlShift14	xba	asl a	asl a	xba	rtlShift15	xba	asl a	xba	rtl	ENDP	END